    def prepare_post_toolbar(self, scenario: RequestScenario) -> None:
        """Render a POST action using the existing navigation callback as a harmless fixture."""
        self.prepare_custom_toolbar(scenario)
        settings = CalendarEvent.bloomerp_config.model_view_settings
        actions = [
            action.model_copy(update={"method": "POST"})
            if isinstance(action, DataviewAction) else action
            for action in settings.dataview_actions
        ]
        self.enterContext(patch.object(settings, "dataview_actions", actions))

    def prepare_post_action(self, scenario: RequestScenario) -> None:
        """Resolve a POST-only action to verify method enforcement at execution time."""
        self.prepare_post_toolbar(scenario)
        self.prepare_calendar_action(scenario)

    def prepare_calendar_action(self, scenario: RequestScenario) -> None:
        """Resolve the real calendar action without creating or modifying an event."""
        Inbox.objects.get_or_create(pk=1, defaults={"user": self.admin_user, "name": "Test Inbox"})
        scenario.view_kwargs = {
            "content_type_id": ContentType.objects.get_for_model(CalendarEvent).pk,
            "action_id": "back_to_inbox",
        }

    def prepare_custom_toolbar(self, scenario: RequestScenario) -> None:
        """Temporarily configure attributes on the real Back to Inbox toolbar action."""
        Inbox.objects.get_or_create(pk=1, defaults={"user": self.admin_user, "name": "Test Inbox"})
        scenario.view_kwargs = {
            "content_type_id": ContentType.objects.get_for_model(CalendarEvent).pk,
        }
        settings = CalendarEvent.bloomerp_config.model_view_settings
        actions = [
            action.model_copy(update={
                "button_attrs": {
                    "title": 'A "quoted" title',
                    "data-navigation": "inbox",
                }
            }) if isinstance(action, DataviewAction) else action
            for action in settings.dataview_actions
        ]
        self.enterContext(patch.object(settings, "dataview_actions", actions))

    def opens_inbox(self, response: HttpResponse) -> bool:
        """Require navigation to the Inbox page inside the main content panel."""
        location = json.loads(response.headers["HX-Location"])
        return location["path"] == reverse("inbox") and location["target"] == "#main-content"

    @staticmethod
    def context_response(context: DataviewActionContext) -> HttpResponse:
        """Return the public context values received by an actual action callback."""
        return JsonResponse({
            "filters": [group.model_dump() for group in context.filters],
            "selected_ids": context.selected_ids,
            "rows": list(context.queryset.values_list("pk", flat=True)),
        })

    def prepare_context_action(self, scenario: RequestScenario) -> None:
        """Create visible and excluded rows and install a context-reporting action."""
        self.selected = self.CustomerModel.objects.create(first_name="Selected", age=45)
        self.excluded = self.CustomerModel.objects.create(first_name="Excluded", age=20)
        self.unselected = self.CustomerModel.objects.create(first_name="Unselected", age=50)
        self.applied_filters = [{"connector": "AND", "conditions": [
            {"field_path": "age", "lookup_id": "greater_than", "value": 30},
        ]}]
        scenario.view_kwargs = {
            "content_type_id": ContentType.objects.get_for_model(self.CustomerModel).pk,
            "action_id": "context",
        }
        scenario.query_params = {"filter": json.dumps(self.applied_filters)}
        scenario.data = {"selected_ids": [str(self.selected.pk), str(self.excluded.pk), str(self.selected.pk)]}
        config = BloomerpModelConfig(model_view_settings=ModelViewSettings(dataview_actions=[
            DataviewAction(id="context", label="Context", execution_func=self.context_response),
        ]))
        self.enterContext(patch.object(self.CustomerModel, "bloomerp_config", config, create=True))

    def prepare_get_context_action(self, scenario: RequestScenario) -> None:
        """Move selection into GET parameters for an explicitly GET action."""
        self.prepare_context_action(scenario)
        scenario.query_params.update(scenario.data)
        scenario.data = {}
        self.CustomerModel.bloomerp_config.model_view_settings.dataview_actions[0].method = "GET"

    def prepare_denied_selection(self, scenario: RequestScenario) -> None:
        """Keep attempted selections while removing filters that require field grants."""
        self.prepare_context_action(scenario)
        scenario.query_params = {}
        self.normal_user.user_permissions.add(Permission.objects.get(
            content_type_id=scenario.view_kwargs["content_type_id"], codename="view_customer",
        ))

    def prepare_invalid_selection(self, scenario: RequestScenario) -> None:
        """Submit an invalid primary key through the real action endpoint."""
        self.prepare_context_action(scenario)
        scenario.data = {"selected_ids": ["invalid-primary-key"]}

    def receives_filtered_selection(self, response: HttpResponse) -> bool:
        """Verify filters, deduplicated selection, and the full filtered queryset."""
        payload = json.loads(response.content)
        return (
            payload["filters"] == self.applied_filters
            and payload["selected_ids"] == [str(self.selected.pk)]
            and set(payload["rows"]) == {str(self.selected.pk), str(self.unselected.pk)}
        )

    def receives_no_rows(self, response: HttpResponse) -> bool:
        """Verify no-policy callers receive neither selected IDs nor rows."""
        payload = json.loads(response.content)
        return payload["selected_ids"] == [] and payload["rows"] == []

    @staticmethod
    def html_context(context: DataviewActionContext) -> dict[str, str]:
        """Build visible template data from the public dataview action context."""
        return {"custom_text": f"Custom context: {len(context.selected_ids)} selected"}

    @staticmethod
    def modal_endpoint(context: DataviewActionContext) -> str:
        """Provide a modal endpoint without invoking it during toolbar rendering."""
        return "/review/"

    def prepare_html_toolbar(self, scenario: RequestScenario) -> None:
        """Render real HTML/modal actions with a temporary custom action template."""
        self.prepare_context_action(scenario)
        scenario.view_kwargs.pop("action_id")
        scenario.data = {}
        scenario.query_params["selected_ids"] = [str(self.selected.pk)]
        actions = [
            DataviewHTMLAction(id="summary", template_name="action_context.html", context_func=self.html_context),
            DataviewModalAction(id="review", label="Review selection", endpoint=self.modal_endpoint),
        ]
        self.CustomerModel.bloomerp_config.model_view_settings.dataview_actions = actions
        directory = self.enterContext(TemporaryDirectory())
        Path(directory, "action_context.html").write_text("{{ custom_text }}", encoding="utf-8")
        templates = deepcopy(settings.TEMPLATES)
        templates[0]["DIRS"] = [directory, *templates[0]["DIRS"]]
        self.enterContext(override_settings(TEMPLATES=templates))
